private validateLegacyThreadReadSnapshot(
  data: AgentTeamThreadReadSnapshot,
  projection: Projection,
  target: { readonly threadRef?: AgentTeamThreadRef | undefined; readonly taskRef?: AgentTeamTaskRef | undefined },
